create or replace function public.sync_installment_from_payment_request() returns trigger language plpgsql security definer set search_path=public as $$ declare v_order_id uuid; inst public.order_installments; remaining numeric:=coalesce(new.amount,0); applied numeric; new_paid numeric; new_balance numeric; begin if new.status not in ('approved','completed','paid') or new.related_payment_id is null then return new; end if; if lower(coalesce(new.type,'')) like '%document%' then return new; end if; select o.id into v_order_id from public.payments p join public.orders o on o.payment_reference=p.payment_reference where p.id=new.related_payment_id limit 1; if v_order_id is null then select o.id into v_order_id from public.orders o where o.payment_reference=new.reference limit 1; end if; if v_order_id is null or remaining<=0 then return new; end if; perform public.rebuild_order_installments(v_order_id); if remaining > (select greatest(total_amount-coalesce(amount_paid,0),0) from public.orders where id=v_order_id) then raise exception 'Payment amount exceeds authoritative order balance'; end if; for inst in select * from public.order_installments where order_id=v_order_id and status not in ('paid','cancelled') and greatest(amount_due-coalesce(amount_paid,0),0)>0 order by installment_number,payment_sequence nulls first for update loop exit when remaining<=0; applied:=least(remaining,greatest(inst.amount_due-coalesce(inst.amount_paid,0),0)); update public.order_installments set amount_paid=coalesce(amount_paid,0)+applied,status=case when coalesce(amount_paid,0)+applied>=amount_due then 'paid' else 'partial' end,payment_id=new.related_payment_id,payment_reference=new.reference,paid_at=case when coalesce(amount_paid,0)+applied>=amount_due then now() else paid_at end,updated_at=now() where id=inst.id; remaining:=remaining-applied; end loop; select coalesce(sum(amount_paid),0) into new_paid from public.order_installments where order_id=v_order_id; update public.orders set amount_paid=least(total_amount,new_paid),balance=greatest(total_amount-least(total_amount,new_paid),0),payment_status=case when greatest(total_amount-least(total_amount,new_paid),0)<=0 then 'paid' else 'pending' end,updated_at=now() where id=v_order_id returning balance into new_balance; return new; end; $$; create or replace function public.admin_approve_payment_request(_request_id uuid,_decision text,_notes text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare r public.payment_requests; caller uuid:=auth.uid(); o public.orders; begin if caller is null then raise exception 'Authentication required'; end if; if not public.user_has_permission(caller,'admin:approve_payments') then raise exception 'You do not have permission to approve payments'; end if; if lower(_decision) not in ('approved','rejected') then raise exception 'Invalid payment decision'; end if; select * into r from public.payment_requests where id=_request_id for update; if not found then raise exception 'Payment request not found'; end if; if r.status<>'pending' then raise exception 'Payment request is already processed'; end if; if lower(_decision)='approved' then if r.amount<=0 then raise exception 'Invalid payment amount'; end if; select public.resolve_payment_order(r.id) into o; if o.id is not null and lower(coalesce(r.type,'')) not like '%document%' then if r.amount>greatest(o.total_amount-coalesce(o.amount_paid,0),0) then raise exception 'Payment amount exceeds the outstanding order balance'; end if; end if; update public.payment_requests set status='approved',processed_by=caller,processed_at=now(),admin_notes=nullif(trim(coalesce(_notes,'')),'') where id=r.id; update public.estate_documentation_payments set status='paid',updated_at=now() where reference=r.reference and status='awaiting_approval'; update public.payments set status=case when lower(coalesce(r.type,'')) like '%document%' then 'completed' when balance<=0 then 'completed' else 'active' end,updated_at=now() where reference=r.reference and status='awaiting_approval'; select public.resolve_payment_order(r.id) into o; return jsonb_build_object('success',true,'request_id',r.id,'decision','approved','order_id',o.id,'amount_paid',coalesce(o.amount_paid,0),'balance',coalesce(o.balance,0)); else update public.payment_requests set status='rejected',processed_by=caller,processed_at=now(),admin_notes=nullif(trim(coalesce(_notes,'')),'') where id=r.id; update public.orders set payment_status='rejected',updated_at=now() where payment_reference=r.reference and payment_status='awaiting_approval'; update public.estate_documentation_payments set status='rejected',updated_at=now() where reference=r.reference and status='awaiting_approval'; update public.payments set status='rejected',updated_at=now() where reference=r.reference and status='awaiting_approval'; return jsonb_build_object('success',true,'request_id',r.id,'decision','rejected'); end if; end; $$; grant execute on function public.admin_approve_payment_request(uuid,text,text) to authenticated;
